class Solution:
    def sumOfGoodNumbers(self, nums: List[int], k: int) -> int:
        total = 0
        n = len(nums)
        for i, x in enumerate(nums):
            left_ok = (i - k < 0) or (x > nums[i - k])
            right_ok = (i + k >= n) or (x > nums[i + k])
            if left_ok and right_ok:
                total += x
        return total

