class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        # prefix sums
        S = [0] * (n + 1)
        for i in range(n):
            S[i + 1] = S[i] + nums[i]

        NEG = float('-inf')

        # dp_prev[p] = max sum using j-1 subarrays within the first p elements
        dp_prev = [0.0] * (n + 1)  # j = 0: zero subarrays, sum 0

        for j in range(1, k + 1):
            dp_curr = [NEG] * (n + 1)
            best = NEG       # max over p <= i - m of (dp_prev[p] - S[p])
            prev_curr = NEG  # dp_curr[i - 1]
            pm = dp_prev
            for i in range(n + 1):
                if i >= m:
                    cand = pm[i - m] - S[i - m]
                    if cand > best:
                        best = cand
                    # last subarray ends at i (indices p..i-1, length >= m)
                    val = S[i] + best
                    if prev_curr > val:
                        val = prev_curr  # element i-1 unused
                else:
                    val = prev_curr
                dp_curr[i] = val
                prev_curr = val
            dp_prev = dp_curr

        return int(dp_prev[n])

